/**
 * AutoFyon — Universal Brand Ingestion & Validation Engine
 *
 * This script accepts a clean, standardized brand JSON (which can be generated by
 * ANY AI model, including small local models like Ollama, Llama 3, or Mistral)
 * and performs strict validation, image conflict resolution, brochure registration,
 * and generates idempotent SQL ready for Cloudflare D1.
 *
 * Usage:
 *   node scripts/ingest_brand.js --file path/to/brand.json
 *   node scripts/ingest_brand.js --file path/to/brand.json --execute
 */

const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

function escapeSql(str) {
  if (str === null || str === undefined) return 'NULL';
  return `'${String(str).replace(/'/g, "''")}'`;
}

const gallerySectionIds = new Set([
  'sec_1_identity',
  'sec_auto_specs',
  'sec_auto_exterior',
  'sec_auto_interior',
  'sec_auto_engine',
  'sec_auto_comfort',
  'sec_auto_safety',
  'sec_auto_technology',
]);
const modelRelations = new Set([
  'sold_by', 'distributed_by', 'manufactured_at', 'serviced_by',
  'insured_by', 'financed_by', 'parts_for', 'compatible_with',
]);

function normalizeImage(image) {
  if (typeof image === 'string') {
    return { url: image, section_id: 'sec_1_identity' };
  }
  if (!image || typeof image !== 'object' || Array.isArray(image)) return null;
  return {
    url: image.url,
    section_id: image.section_id || 'sec_1_identity',
    caption: image.caption,
    caption_ar: image.caption_ar,
    source_url: image.source_url,
    source_id: image.source_id,
    field_key: image.field_key,
    field_section_id: image.field_section_id,
    placement: image.placement,
    exact_feature_proof: image.exact_feature_proof,
    review_status: image.review_status,
  };
}

function validateBrandPayload(payload) {
  const errors = [];
  const warnings = [];

  if (!payload.brand || !payload.brand.slug || !payload.brand.name) {
    errors.push('brand.slug and brand.name are required.');
  }

  if (!payload.models || !Array.isArray(payload.models) || payload.models.length === 0) {
    errors.push('At least one model is required in payload.models.');
  }
  if (payload.sources !== undefined && !Array.isArray(payload.sources)) {
    errors.push('sources must be an array when provided.');
  }
  const sourceIds = new Set();
  (Array.isArray(payload.sources) ? payload.sources : []).forEach((source, sourceIdx) => {
    if (!source || typeof source !== 'object' || Array.isArray(source) ||
        typeof source.id !== 'string' || !source.id.trim()) {
      errors.push(`sources[${sourceIdx}] must include a non-empty id.`);
      return;
    }
    if (sourceIds.has(source.id)) errors.push(`Duplicate source id "${source.id}".`);
    sourceIds.add(source.id);
    if (typeof source.url !== 'string' || !/^https?:\/\//i.test(source.url)) {
      errors.push(`Source "${source.id}" must have an absolute HTTP/HTTPS url.`);
    }
  });
  const validateSourceRefs = (refs, context) => {
    if (refs === undefined) return;
    if (!refs || typeof refs !== 'object' || Array.isArray(refs)) {
      errors.push(`${context} source_refs must be an object.`);
      return;
    }
    if (Array.isArray(payload.sources)) {
      Object.entries(refs).forEach(([field, sourceId]) => {
        if (typeof sourceId !== 'string' || !sourceIds.has(sourceId)) {
          errors.push(`${context} source_refs["${field}"] does not resolve to sources[].id.`);
        }
      });
    }
  };

  // Cross-Model Image Conflict Detection
  const seenImageUrls = new Map();

  payload.models?.forEach((m, mIdx) => {
    if (!m.slug || !m.name) {
      errors.push(`Model at index ${mIdx} is missing slug or name.`);
    }
    if (m.market_comparisons !== undefined && !Array.isArray(m.market_comparisons)) {
      errors.push(`Model "${m.name}" market_comparisons must be an array when provided.`);
    }
    if (m.relationships !== undefined && !Array.isArray(m.relationships)) {
      errors.push(`Model "${m.name}" relationships must be an array when provided.`);
    }
    (Array.isArray(m.relationships) ? m.relationships : []).forEach((relationship, relationshipIdx) => {
      if (!relationship || typeof relationship !== 'object' || Array.isArray(relationship)) {
        errors.push(`Model "${m.name}" relationships[${relationshipIdx}] must be an object.`);
        return;
      }
      if (!modelRelations.has(relationship.relation_type)) {
        errors.push(`Model "${m.name}" relationships[${relationshipIdx}] has unsupported relation_type.`);
      }
      if (typeof relationship.provider_business_id !== 'string' || !relationship.provider_business_id.trim()) {
        errors.push(`Model "${m.name}" relationships[${relationshipIdx}] requires provider_business_id from an existing AutoFyon record.`);
      }
      if (relationship.relation_type === 'parts_for' && relationship.direction !== 'in') {
        errors.push(`Model "${m.name}" parts_for relationships must use direction "in".`);
      }
      if (relationship.direction !== undefined && !['in', 'out'].includes(relationship.direction)) {
        errors.push(`Model "${m.name}" relationships[${relationshipIdx}] direction must be "in" or "out".`);
      }
      if (relationship.source_id && Array.isArray(payload.sources) && !sourceIds.has(relationship.source_id)) {
        errors.push(`Model "${m.name}" relationships[${relationshipIdx}] source_id does not resolve to sources[].id.`);
      }
      if (relationship.role_data !== undefined &&
          (!relationship.role_data || typeof relationship.role_data !== 'object' || Array.isArray(relationship.role_data))) {
        errors.push(`Model "${m.name}" relationships[${relationshipIdx}] role_data must be an object.`);
      }
    });
    if (Array.isArray(m.market_comparisons) && m.market_comparisons.length && !Array.isArray(payload.sources)) {
      errors.push(`Model "${m.name}" market_comparisons require a top-level sources[] registry.`);
    }
    (Array.isArray(m.market_comparisons) ? m.market_comparisons : []).forEach((comparison, comparisonIdx) => {
      if (!comparison || typeof comparison !== 'object' || Array.isArray(comparison)) {
        errors.push(`Model "${m.name}" market_comparisons[${comparisonIdx}] must be an object.`);
        return;
      }
      const required = [
        ['attribute_en', comparison.attribute_en || comparison.attribute_or_field_key],
        ['egypt_value', comparison.egypt_value],
        ['egypt_source_id', comparison.egypt_source_id],
        ['egypt_source_url', comparison.egypt_source_url],
        ['gcc_country', comparison.gcc_country],
        ['gcc_trim_name', comparison.gcc_trim_name],
        ['gcc_value', comparison.gcc_value],
        ['gcc_source_id', comparison.gcc_source_id],
        ['gcc_source_url', comparison.gcc_source_url],
      ];
      for (const [field, value] of required) {
        if (typeof value !== 'string' || !value.trim()) {
          errors.push(`Model "${m.name}" market_comparisons[${comparisonIdx}] requires ${field}.`);
        }
      }
      if (!((typeof comparison.gcc_model_year === 'string' && comparison.gcc_model_year.trim()) ||
            (typeof comparison.gcc_model_year === 'number' && Number.isFinite(comparison.gcc_model_year)))) {
        errors.push(`Model "${m.name}" market_comparisons[${comparisonIdx}] requires gcc_model_year.`);
      }
      if (Array.isArray(payload.sources)) {
        for (const field of ['egypt_source_id', 'gcc_source_id']) {
          if (!sourceIds.has(comparison[field])) {
            errors.push(`Model "${m.name}" market_comparisons[${comparisonIdx}] ${field} does not resolve to sources[].id.`);
          }
        }
      }
      if (!comparison.review_status) {
        warnings.push(`Model "${m.name}" market comparison ${comparisonIdx + 1} has no review_status and will not display publicly.`);
      }
      for (const field of ['egypt_source_url', 'gcc_source_url']) {
        if (comparison[field] !== undefined && comparison[field] !== null &&
            (typeof comparison[field] !== 'string' || !/^https?:\/\//i.test(comparison[field]))) {
          errors.push(`Model "${m.name}" market_comparisons[${comparisonIdx}] ${field} must be an absolute HTTP/HTTPS URL.`);
        }
      }
      if (comparison.review_status && String(comparison.review_status).toUpperCase() !== 'APPROVED') {
        warnings.push(`Model "${m.name}" market comparison ${comparisonIdx + 1} is not approved and will not display publicly.`);
      }
    });

    // Brochure validation
    if (!m.brochure_url) {
      warnings.push(`Model "${m.name}" has no brochure_url specified.`);
    } else if (!m.brochure_url.startsWith('http')) {
      errors.push(`Model "${m.name}" brochure_url must be an absolute HTTP/HTTPS URL.`);
    }

    // Images validation
    if (!m.images || !Array.isArray(m.images) || m.images.length === 0) {
      warnings.push(`Model "${m.name}" has no images in gallery.`);
    } else {
      m.images.forEach((image, imgIdx) => {
        const normalized = normalizeImage(image);
        if (!normalized || typeof normalized.url !== 'string' || !normalized.url.startsWith('http')) {
          errors.push(`Model "${m.name}" image[${imgIdx}] must be a URL string or an object with an absolute HTTP/HTTPS url.`);
          return;
        }
        const {
          url, section_id, caption, caption_ar, source_url, source_id,
          field_key, field_section_id, placement, exact_feature_proof, review_status,
        } = normalized;
        if (typeof section_id !== 'string' || !gallerySectionIds.has(section_id)) {
          errors.push(`Model "${m.name}" image[${imgIdx}] has unsupported section_id "${section_id}".`);
        }
        if (caption !== undefined && typeof caption !== 'string') {
          errors.push(`Model "${m.name}" image[${imgIdx}] caption must be a string.`);
        }
        if (caption_ar !== undefined && typeof caption_ar !== 'string') {
          errors.push(`Model "${m.name}" image[${imgIdx}] caption_ar must be a string.`);
        }
        if (source_url !== undefined && (typeof source_url !== 'string' || !source_url.startsWith('https://'))) {
          errors.push(`Model "${m.name}" image[${imgIdx}] source_url must be an absolute HTTPS URL.`);
        }
        if (source_id !== undefined && typeof source_id !== 'string') {
          errors.push(`Model "${m.name}" image[${imgIdx}] source_id must be a string.`);
        }
        if (source_id && Array.isArray(payload.sources) && !sourceIds.has(source_id)) {
          errors.push(`Model "${m.name}" image[${imgIdx}] source_id does not resolve to sources[].id.`);
        }
        if (Boolean(field_key) !== Boolean(field_section_id)) {
          errors.push(`Model "${m.name}" image[${imgIdx}] must provide both field_key and field_section_id for a field-bound image.`);
        }
        if (field_key && !String(field_key).trim()) {
          errors.push(`Model "${m.name}" image[${imgIdx}] field_key must not be empty.`);
        }
        if (field_section_id && !gallerySectionIds.has(field_section_id)) {
          errors.push(`Model "${m.name}" image[${imgIdx}] has unsupported field_section_id "${field_section_id}".`);
        }
        if (placement !== undefined && !['body', 'carousel', 'both'].includes(placement)) {
          errors.push(`Model "${m.name}" image[${imgIdx}] placement must be body, carousel, or both.`);
        }
        if (field_key && placement === 'body') {
          errors.push(`Model "${m.name}" image[${imgIdx}] is field-bound but placement is body; use carousel or both.`);
        }
        if (field_key) {
          if (typeof source_id !== 'string' || !source_id.trim()) {
            errors.push(`Model "${m.name}" field-bound image[${imgIdx}] requires source_id.`);
          }
          if (typeof source_url !== 'string' || !/^https:\/\//i.test(source_url)) {
            errors.push(`Model "${m.name}" field-bound image[${imgIdx}] requires an HTTPS source_url.`);
          }
          if (typeof exact_feature_proof !== 'string' || !exact_feature_proof.trim()) {
            errors.push(`Model "${m.name}" field-bound image[${imgIdx}] requires exact_feature_proof.`);
          }
          if (typeof review_status !== 'string' || review_status.toUpperCase() !== 'APPROVED') {
            errors.push(`Model "${m.name}" field-bound image[${imgIdx}] must have review_status "APPROVED".`);
          }
        }
        // Conflict check: ensure this image is not assigned to another model
        if (seenImageUrls.has(url)) {
          errors.push(
            `IMAGE CONFLICT: Image URL "${url}" is used in both model "${seenImageUrls.get(url)}" and "${m.name}". Images must strictly belong to their own model.`
          );
        } else {
          seenImageUrls.set(url, m.name);
        }

        // Placeholder prohibition check
        if (url.includes('unsplash.com') || url.includes('placeholder') || url.includes('picsum.photos')) {
          errors.push(
            `FORBIDDEN PLACEHOLDER: Image "${url}" for model "${m.name}" is a generic placeholder. Only official agent assets are allowed.`
          );
        }
      });
    }

    // Trims validation
    if (!m.trims || !Array.isArray(m.trims) || m.trims.length === 0) {
      warnings.push(`Model "${m.name}" has no trims defined.`);
    } else {
      m.trims.forEach((t, tIdx) => {
        if (!t.slug || !t.name) {
          errors.push(`Model "${m.name}" trim[${tIdx}] is missing slug or name.`);
        }
        if (t.price_egp !== undefined && t.price_egp !== null &&
            (!Number.isInteger(t.price_egp) || t.price_egp <= 0)) {
          errors.push(`Model "${m.name}" trim "${t.name}" price_egp must be a positive integer.`);
        }
        validateSourceRefs(t.source_refs, `Model "${m.name}" trim "${t.name}"`);
      });
    }
    validateSourceRefs(m.source_refs, `Model "${m.name}"`);

    const mappedSpecImages = new Set(
      (Array.isArray(m.images) ? m.images : [])
        .map(normalizeImage)
        .filter((image) => image && image.field_key && image.field_section_id)
        .map((image) => `${image.field_section_id}::${image.field_key}`),
    );
    const sectionSpecs = {
      ...(m.specs ? { sec_auto_specs: m.specs } : {}),
      ...(m.spec_sections || {}),
    };
    for (const [sectionId, values] of Object.entries(sectionSpecs)) {
      if (!values || typeof values !== 'object' || Array.isArray(values)) continue;
      for (const [fieldKey, value] of Object.entries(values)) {
        if (fieldKey.endsWith('_ar') || value === null || value === undefined || value === '' ||
            fieldKey === 'market_comparisons') continue;
        if (!mappedSpecImages.has(`${sectionId}::${fieldKey}`)) {
          if (mappedSpecImages.size > 0) {
            errors.push(`Model "${m.name}" specification "${sectionId}.${fieldKey}" has no matching field-bound image in images[].`);
          } else {
            warnings.push(`Model "${m.name}" specification "${sectionId}.${fieldKey}" has no matching field-bound image in images[].`);
          }
        }
      }
    }
  });

  return { errors, warnings };
}

function generateSql(payload) {
  const sql = [];
  const now = new Date().toISOString().replace('T', ' ').substring(0, 19);
  const brand = payload.brand;
  const brandId = `biz_brand_${brand.slug.toLowerCase().replace(/[^a-z0-9]/g, '_')}`;
  const brandSlug = brand.slug.toLowerCase();

  sql.push(`-- ========================================================`);
  sql.push(`-- Brand Ingestion: ${brand.name} (${brand.name_ar || ''})`);
  sql.push(`-- Generated: ${now}`);
  sql.push(`-- ========================================================\n`);

  // 1. Brand Row
  const brandCustomData = JSON.stringify({
    sec_1_identity: {
      brand_origin: brand.origin || null,
      official_website: payload.agency?.website || null,
      ...(brand.logo_url ? { logo_url: brand.logo_url } : {}),
    },
    ...(Array.isArray(payload.sources) ? { _data_provenance: { sources: payload.sources } } : {}),
  });

  sql.push(`-- 1. Register / Update Brand Node`);
  sql.push(`INSERT INTO businesses (
  id, name, name_ar, slug, type_id, market_id, parent_business_id, path,
  minisite_mode, url_style, subscription_tier, status, published, custom_data
) VALUES (
  ${escapeSql(brandId)},
  ${escapeSql(brand.name)},
  ${escapeSql(brand.name_ar || brand.name)},
  ${escapeSql(brandSlug)},
  'vehicle_brand',
  'automotive',
  NULL,
  ${escapeSql('/' + brandSlug)},
  'standalone',
  'root',
  'enterprise',
  'active',
  1,
  ${escapeSql(brandCustomData)}
) ON CONFLICT(id) DO UPDATE SET
  name = excluded.name,
  name_ar = excluded.name_ar,
  published = 1,
  custom_data = json_patch(businesses.custom_data, excluded.custom_data);
`);

  // 2. Official Agency / Distributor (if provided)
  let agencyId = null;
  if (payload.agency) {
    const agency = payload.agency;
    agencyId = agency.id || `biz_dist_${agency.slug.toLowerCase().replace(/[^a-z0-9]/g, '_')}`;
    const agencyType = agency.type_id || 'distributor';
    const agencyCustomData = JSON.stringify({
      sec_vendor_identity: {
        company_name: agency.name,
        company_name_ar: agency.name_ar || agency.name,
        phone: agency.phone || null,
        website: agency.website || null,
        official_brands: [brand.name],
      },
    });

    sql.push(`-- 2. Register Official Agency / Distributor`);
    sql.push(`INSERT INTO businesses (
  id, name, name_ar, slug, type_id, market_id, parent_business_id, path,
  minisite_mode, url_style, subscription_tier, status, published, custom_data
) VALUES (
  ${escapeSql(agencyId)},
  ${escapeSql(agency.name)},
  ${escapeSql(agency.name_ar || agency.name)},
  ${escapeSql(agency.slug.toLowerCase())},
  ${escapeSql(agencyType)},
  'automotive',
  NULL,
  ${escapeSql('/' + agency.slug.toLowerCase())},
  'standalone',
  'root',
  'enterprise',
  'active',
  1,
  ${escapeSql(agencyCustomData)}
) ON CONFLICT(id) DO UPDATE SET
  name = excluded.name,
  name_ar = excluded.name_ar,
  published = 1,
  custom_data = json_patch(businesses.custom_data, excluded.custom_data);
`);
  }

  // 2b. Agency Showrooms / Centers / Branches (if provided)
  if (Array.isArray(payload.showrooms) && payload.showrooms.length > 0) {
    payload.showrooms.forEach((sh) => {
      const shSlug = sh.slug.toLowerCase();
      const shId = sh.id || `biz_showroom_${brandSlug}_${shSlug.replace(/[^a-z0-9]/g, '_')}`;
      const shType = sh.type_id || 'showroom';
      const shCustomData = JSON.stringify({
        sec_vendor_identity: {
          company_name: sh.name,
          company_name_ar: sh.name_ar || sh.name,
          phone: sh.phone || null,
          address: sh.address || null,
          city: sh.city || null,
          governorate: sh.governorate || null,
        },
      });

      sql.push(`INSERT INTO businesses (
  id, name, name_ar, slug, type_id, market_id, parent_business_id, path,
  minisite_mode, url_style, subscription_tier, status, published, custom_data
) VALUES (
  ${escapeSql(shId)},
  ${escapeSql(sh.name)},
  ${escapeSql(sh.name_ar || sh.name)},
  ${escapeSql(shSlug)},
  ${escapeSql(shType)},
  'automotive',
  ${escapeSql(agencyId)},
  ${escapeSql('/' + shSlug)},
  'embedded',
  'root',
  'enterprise',
  'active',
  1,
  ${escapeSql(shCustomData)}
) ON CONFLICT(id) DO UPDATE SET
  name = excluded.name,
  name_ar = excluded.name_ar,
  published = 1,
  custom_data = json_patch(businesses.custom_data, excluded.custom_data);
`);
    });
  }

  // 3. Models, Trims, Gallery, and Relationships
  payload.models.forEach((m) => {
    const modelSlug = m.slug.toLowerCase();
    const modelId = m.id || `biz_model_${brandSlug}_${modelSlug.replace(/[^a-z0-9]/g, '_')}`;
    const modelPath = `/${brandSlug}/${modelSlug}`;
    const sectionSpecs = {
      ...(m.specs ? { sec_auto_specs: m.specs } : {}),
      ...(m.spec_sections || {}),
    };
    if (Array.isArray(m.market_comparisons)) {
      sectionSpecs.sec_auto_specs = {
        ...(sectionSpecs.sec_auto_specs || {}),
        market_comparisons: m.market_comparisons,
      };
    }
    const simpleSpecs = (values) => Object.fromEntries(
      Object.entries(values || {}).filter(([key]) => key !== 'market_comparisons'),
    );
    const officialSpecs = {
      ...simpleSpecs(m.specs),
      ...Object.assign({}, ...Object.values(m.spec_sections || {}).map(simpleSpecs)),
    };

    const identity = {
      category: m.category || 'Sedan',
      model_name: m.name,
      model_name_ar: m.name_ar || m.name,
      official_specs: officialSpecs,
      ...(m.year ? { year: m.year } : {}),
      ...(m.brochure_url ? { brochure_url: m.brochure_url } : {}),
    };
    // Roll up first trim's specs to model level so carousel summary works
    const firstTrimSpecs = (Array.isArray(m.trims) && m.trims.length > 0 && m.trims[0].specs)
      ? m.trims[0].specs : null;
    const firstTrimPrice = (Array.isArray(m.trims) && m.trims.length > 0 && m.trims[0].price_egp)
      ? m.trims[0].price_egp : null;

    const modelCustomData = JSON.stringify({
      sec_1_identity: identity,
      ...sectionSpecs,
      // Model-level spec rollup from first trim — powers the carousel spec summary note
      ...(firstTrimSpecs && !sectionSpecs.sec_auto_specs ? { sec_auto_specs: firstTrimSpecs } : {}),
      ...(firstTrimPrice ? {
        sec_listing_price: {
          official_price_egp: firstTrimPrice,
          currency: 'EGP',
          price_note: (Array.isArray(m.trims) && m.trims[0].price_note) || null,
          price_note_ar: (Array.isArray(m.trims) && m.trims[0].price_note_ar) || null,
          trim_range: Array.isArray(m.trims) ? {
            min: Math.min(...m.trims.filter(t => t.price_egp).map(t => t.price_egp)),
            max: Math.max(...m.trims.filter(t => t.price_egp).map(t => t.price_egp)),
            count: m.trims.filter(t => t.price_egp).length,
          } : null,
        },
      } : {}),
      ...(m.brochure_url ? { sec_overview: { brochure_url: m.brochure_url } } : {}),
      ...(m.source_refs || m.source_ids ? {
        _data_provenance: {
          ...(m.source_ids ? { source_ids: m.source_ids } : {}),
          ...(m.source_refs ? { field_sources: m.source_refs } : {}),
        },
      } : {}),
    });

    sql.push(`-- ── Model: ${brand.name} ${m.name} ─────────────────────────────`);
    sql.push(`INSERT INTO businesses (
  id, name, name_ar, slug, type_id, market_id, parent_business_id, path,
  minisite_mode, url_style, subscription_tier, status, published, custom_data
) VALUES (
  ${escapeSql(modelId)},
  ${escapeSql(m.name)},
  ${escapeSql(m.name_ar || m.name)},
  ${escapeSql(modelSlug)},
  'vehicle_model',
  'automotive',
  ${escapeSql(brandId)},
  ${escapeSql(modelPath)},
  'standalone',
  'root',
  'enterprise',
  'active',
  1,
  ${escapeSql(modelCustomData)}
) ON CONFLICT(id) DO UPDATE SET
  name = excluded.name,
  name_ar = excluded.name_ar,
  slug = excluded.slug,
  parent_business_id = excluded.parent_business_id,
  published = 1,
  custom_data = json_patch(businesses.custom_data, excluded.custom_data);
`);

    // Relationship: sold_by agency
    if (agencyId) {
      const edgeId = `edge_${modelId}_sold_by_${agencyId}`;
      sql.push(`INSERT INTO business_relationships (
        id, from_business_id, to_business_id, relation_type, is_primary
) VALUES (
  ${escapeSql(edgeId)},
  ${escapeSql(modelId)},
  ${escapeSql(agencyId)},
  'sold_by',
  1
) ON CONFLICT(from_business_id, to_business_id, relation_type) DO UPDATE SET is_primary = 1;
`);
    }

    (Array.isArray(m.relationships) ? m.relationships : []).forEach((relationship, relationshipIdx) => {
      const direction = relationship.direction || 'out';
      const fromBusinessId = direction === 'in' ? relationship.provider_business_id : modelId;
      const toBusinessId = direction === 'in' ? modelId : relationship.provider_business_id;
      const relationshipId = `edge_${modelId}_${relationship.relation_type}_${relationship.provider_business_id}`
        .replace(/[^a-zA-Z0-9_-]/g, '_');
      const roleData = {
        ...(relationship.role_data || {}),
        ...(relationship.source_id ? { source_id: relationship.source_id } : {}),
      };
      sql.push(`-- Model service relationship ${relationshipIdx + 1}: ${relationship.relation_type}`);
      sql.push(`INSERT INTO business_relationships (
  id, from_business_id, to_business_id, relation_type, is_primary, role_data
) VALUES (
  ${escapeSql(relationshipId)},
  ${escapeSql(fromBusinessId)},
  ${escapeSql(toBusinessId)},
  ${escapeSql(relationship.relation_type)},
  0,
  ${escapeSql(Object.keys(roleData).length ? JSON.stringify(roleData) : null)}
) ON CONFLICT(from_business_id, to_business_id, relation_type) DO UPDATE SET
  role_data = excluded.role_data;
`);
    });

    // Trims
    if (m.trims && m.trims.length > 0) {
      m.trims.forEach((t) => {
        const trimSlug = t.slug.toLowerCase();
        const trimId = t.id || `biz_trim_${modelSlug}_${trimSlug.replace(/[^a-z0-9]/g, '_')}`;
        const trimSectionData = {
          ...(t.specs ? { sec_auto_specs: t.specs } : {}),
          ...(t.spec_sections || {}),
        };
        const trimCustomData = JSON.stringify({
          sec_listing_price: {
            official_price_egp: t.price_egp || null,
            currency: 'EGP',
          },
          sec_1_identity: {
            trim_name: t.name,
            trim_name_ar: t.name_ar || t.name,
          },
          ...trimSectionData,
          ...(t.source_refs ? { _data_provenance: { field_sources: t.source_refs } } : {}),
        });

        sql.push(`INSERT INTO businesses (
  id, name, name_ar, slug, type_id, market_id, parent_business_id, path,
  minisite_mode, url_style, subscription_tier, status, published, custom_data
) VALUES (
  ${escapeSql(trimId)},
  ${escapeSql(t.name)},
  ${escapeSql(t.name_ar || t.name)},
  ${escapeSql(trimSlug)},
  'vehicle_trim',
  'automotive',
  ${escapeSql(modelId)},
  ${escapeSql(modelPath + '/' + trimSlug)},
  'embedded',
  'root',
  'enterprise',
  'active',
  1,
  ${escapeSql(trimCustomData)}
) ON CONFLICT(id) DO UPDATE SET
  name = excluded.name,
  name_ar = excluded.name_ar,
  parent_business_id = excluded.parent_business_id,
  published = 1,
  custom_data = json_patch(businesses.custom_data, excluded.custom_data);
`);
      });
    }

    // Clean Gallery Images tied strictly to modelId
    if (m.images && m.images.length > 0) {
      sql.push(`-- Reset old gallery for ${modelId} to prevent dangling assets`);
      sql.push(`DELETE FROM vendor_gallery WHERE business_id = ${escapeSql(modelId)};`);

      m.images.forEach((image, idx) => {
        const normalized = normalizeImage(image);
        const isHero = idx === 0 && normalized.section_id === 'sec_1_identity' && !normalized.field_key ? 1 : 0;
        const imgId = `gal_${brandSlug}_${modelSlug}_${idx + 1}`;
        const mediaData = normalized.source_url || normalized.source_id
          ? JSON.stringify({
              ...(normalized.source_url ? { source_url: normalized.source_url } : {}),
              ...(normalized.source_id ? { source_id: normalized.source_id } : {}),
              ...(normalized.exact_feature_proof ? { exact_feature_proof: normalized.exact_feature_proof } : {}),
              ...(normalized.review_status ? { review_status: normalized.review_status } : {}),
            })
          : null;
        sql.push(`INSERT INTO vendor_gallery (
  id, business_id, section_id, url, caption, caption_ar, media_data, field_key, field_section_id, is_hero, display_order, placement, show_on_minisite, approval_status, media_type
) VALUES (
  ${escapeSql(imgId)},
  ${escapeSql(modelId)},
  ${escapeSql(normalized.section_id)},
  ${escapeSql(normalized.url)},
  ${escapeSql(normalized.caption || `${brand.name} ${m.name} - Official Asset ${idx + 1}`)},
  ${escapeSql(normalized.caption_ar || null)},
  ${escapeSql(mediaData)},
  ${escapeSql(normalized.field_key || null)},
  ${escapeSql(normalized.field_section_id || null)},
  ${isHero},
  ${idx},
  ${escapeSql(normalized.placement || (normalized.field_key ? 'carousel' : normalized.section_id === 'sec_1_identity' ? 'both' : 'body'))},
  1,
  'approved',
  'image'
);`);
      });
      sql.push('');
    }
  });

  return sql.join('\n');
}

// ── CLI Runner ───────────────────────────────────────────────────────────────
function main() {
  const args = process.argv.slice(2);
  const fileIdx = args.indexOf('--file');
  const execute = args.includes('--execute');

  if (fileIdx === -1 || !args[fileIdx + 1]) {
    console.error('Usage: node scripts/ingest_brand.js --file <path-to-json> [--execute]');
    process.exit(1);
  }

  const filePath = path.resolve(args[fileIdx + 1]);
  if (!fs.existsSync(filePath)) {
    console.error(`File not found: ${filePath}`);
    process.exit(1);
  }

  const raw = fs.readFileSync(filePath, 'utf8');
  let payload;
  try {
    payload = JSON.parse(raw);
  } catch (err) {
    console.error('Invalid JSON file:', err.message);
    process.exit(1);
  }

  console.log(`\nValidating brand payload for "${payload.brand?.name || 'unknown'}"...`);
  const { errors, warnings } = validateBrandPayload(payload);

  if (warnings.length > 0) {
    console.warn('\n⚠️ WARNINGS:');
    warnings.forEach((w) => console.warn(` - ${w}`));
  }

  if (errors.length > 0) {
    console.error('\n❌ VALIDATION ERRORS:');
    errors.forEach((e) => console.error(` - ${e}`));
    console.error('\nAborted due to validation errors. Fix the JSON before proceeding.');
    process.exit(1);
  }

  console.log('✅ Validation passed! Generating idempotent SQL...');
  const sql = generateSql(payload);

  const outDir = path.resolve(__dirname, '../scripts');
  const outFile = path.join(outDir, `ingest_${payload.brand.slug.toLowerCase()}.sql`);
  fs.writeFileSync(outFile, sql, 'utf8');
  console.log(`✅ SQL written to: ${outFile}`);

  if (execute) {
    console.log(`\n🚀 Executing SQL on remote D1 database (autoportal-d1)...`);
    try {
      execSync(`npx.cmd wrangler d1 execute autoportal-d1 --remote --file="${outFile}"`, {
        stdio: 'inherit',
        cwd: path.resolve(__dirname, '..'),
      });
      console.log(`\n🎉 Brand "${payload.brand.name}" successfully ingested into remote D1!`);
    } catch (err) {
      console.error('Failed to execute SQL on D1:', err.message);
      process.exit(1);
    }
  } else {
    console.log(`\nTo execute on remote database, run:`);
    console.log(`npx.cmd wrangler d1 execute autoportal-d1 --remote --file="${outFile}"`);
  }
}

if (require.main === module) {
  main();
}

module.exports = { validateBrandPayload, generateSql };
